'use strict';
const C=NotesCore,esc=C.esc,$=s=>document.querySelector(s),native=typeof Native!=='undefined';
const paths={note:'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5',search:'M21 21l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 5v14 M5 12h14',star:'m12 3 2.8 5.8 6.2.9-4.5 4.4 1 6.1-5.5-2.9-5.5 2.9 1-6.1L2.5 9.7l6.2-.9Z',pin:'m8 3 8 0-1 6 4 4H5l4-4Z M12 13v8',folder:'M3 6h7l2 3h9v12H3z M3 6V3h7l2 3h7v3',archive:'M3 3h18v5H3z M5 8v13h14V8 M9 12h6',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',check:'m4 12 5 5L20 6',tasks:'M9 5h12 M9 12h12 M9 19h12 M3 5h1 M3 12h1 M3 19h1',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18 M7 14h3 M14 14h3',template:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 2h6l1 4 4 2v8l-4 2-1 4H9l-1-4-4-2V8l4-2Z',menu:'M4 6h16 M4 12h16 M4 18h16',back:'m14 5-7 7 7 7 M7 12h14',more:'M5 12h.1 M12 12h.1 M19 12h.1',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M3 5h18 M3 12h18 M3 19h18',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',share:'M18 3a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M6 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M18 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M8 11l8-5 M8 13l8 5',clip:'m8 12 7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3 M6 14l9-9',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6v6l4 2',close:'m5 5 14 14 M19 5 5 19',copy:'M8 8h13v13H8z M3 16V3h13',edit:'m3 17 12-12 4 4L7 21H3z M15 5l3-3 4 4-3 3',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',tag:'M3 3h9l10 10-9 9L3 12z M7 7h.1',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3z M12 5v17',chart:'M4 21V11 M12 21V3 M20 21V7',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 14h12v8H6z'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.note}"/></svg>`;
const ib=(action,name,label,active=false)=>`<button class="icon-button ${active?'active':''}" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}">${icon(name)}</button>`;
const date=(v,short=false)=>new Intl.DateTimeFormat('tr-TR',short?{day:'numeric',month:'short'}:{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v));
const dayKey=t=>{const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let state=C.initial(),section='all',folder=null,tag='',query='',selected=new Set(),selecting=false,currentId='',modePreview=false,drawer=false,welcome=true,fatal='',historyCaptured=false,calendarDate=dayKey(Date.now()),month=new Date(),timer;
const nativeStatus=()=>{try{return native?JSON.parse(Native.status()):{pin:false,notifications:false}}catch(e){return {pin:false}}};
try{if(native){const r=JSON.parse(Native.loadData());if(!r.ok)throw Error(r.error);if(r.data){state=C.validate(JSON.parse(r.data));welcome=false;}}else{const raw=localStorage.getItem('sadienotes-data');if(raw){state=C.validate(JSON.parse(raw));welcome=false;}}}catch(e){fatal=e.message;welcome=false;}
let lastSaved=JSON.stringify(state);
function persist(){if(fatal)return false;try{const raw=JSON.stringify(state);if(raw===lastSaved)return true;if(native){const err=Native.saveData(raw);if(err)throw Error(err);}else localStorage.setItem('sadienotes-data',raw);lastSaved=raw;status('Kaydedildi');return true;}catch(e){status('Kaydedilemedi',true);toast(e.message||'Depolama dolu. Yedek al ve yer aç.');return false;}}
function status(s,error=false){const el=$('#save-status');if(el){el.textContent=s;el.classList.toggle('error',error);}}
function toast(s){clearTimeout(timer);const el=$('#toast');el.textContent=s;el.classList.add('visible');timer=setTimeout(()=>el.classList.remove('visible'),4000);}
function colors(){document.body.classList.toggle('dark',state.settings.theme==='dark'||state.settings.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.style.setProperty('--editor-size',state.settings.fontSize+'px');}
function note(){return state.notes.find(n=>n.id===currentId);}
function bodyText(n){return C.text(n.mode==='markdown'?C.markdown(n.body):n.body);}
function remember(){const n=note();if(n&&!historyCaptured){n.history.push({time:n.updated,title:n.title,body:n.body,mode:n.mode});n.history=n.history.slice(-10);historyCaptured=true;}}
function touch(){const n=note();if(n)n.updated=Date.now();persist();}
function syncReminders(){const list=state.notes.filter(n=>!n.deletedAt&&!n.archived&&n.reminder>Date.now()).map(n=>({id:n.id,time:n.reminder}));if(native)Native.setReminders(JSON.stringify(list));}
function openNote(id){currentId=id;modePreview=false;historyCaptured=false;drawer=false;render();window.scrollTo(0,0);}
function newNote(template=''){const n=C.makeNote({folder:folder!==null?folder:state.settings.defaultFolder});if(template){const t=templates.find(t=>t.id===template);if(t){n.title=t.title+(template==='daily'?' · '+date(Date.now(),true):'');n.body=t.body;n.color=t.color;n.tasks=t.tasks.map(text=>({id:C.uid(),text,done:false,due:'',priority:'normal'}));}}state.notes.unshift(n);if(persist())openNote(n.id);}
const templates=[
{id:'daily',title:'Günlük sayfam',desc:'Düşünceler, niyetler ve günün küçük güzellikleri.',icon:'sun',color:'rose',body:'<h2>Bugün nasıl hissediyorum?</h2><p><br></p><h2>Bugünün niyeti</h2><p><br></p><h2>İyi ki…</h2><ul><li></li></ul><h2>Günün sonunda</h2><p><br></p>',tasks:['Kendime zaman ayır','Bugünün önemli işini tamamla']},
{id:'meeting',title:'Toplantı notları',desc:'Gündem, kararlar ve takip edilecek işler.',icon:'note',color:'lavender',body:'<h2>Toplantı bilgileri</h2><p>Tarih · Katılımcılar</p><h2>Gündem</h2><ul><li></li></ul><h2>Alınan kararlar</h2><p><br></p><h2>Sonraki adımlar</h2><p><br></p>',tasks:['Kararları gözden geçir','İlgili kişilerle paylaş']},
{id:'study',title:'Ders çalışma notu',desc:'Konu özeti, kavramlar ve tekrar planı.',icon:'book',color:'sage',body:'<h2>Konu ve öğrenme hedefi</h2><p><br></p><h2>Önemli kavramlar</h2><ul><li></li></ul><h2>Kendi cümlelerimle özet</h2><p><br></p><h2>Takıldığım sorular</h2><p><br></p>',tasks:['Konuyu tekrar et','Alıştırmaları çöz']},
{id:'project',title:'Proje planı',desc:'Amaç, kapsam, kilometre taşları ve görevler.',icon:'folder',color:'sky',body:'<h2>Ne yapmak istiyorum?</h2><p><br></p><h2>Kapsam</h2><p><br></p><h2>Kilometre taşları</h2><ol><li>Planlama</li><li>Uygulama</li><li>Değerlendirme</li></ol><h2>Kaynaklar</h2><p><br></p>',tasks:['İlk adımı belirle','Son tarihi planla']},
{id:'book',title:'Okuma günlüğü',desc:'Kitap, alıntılar ve akılda kalan fikirler.',icon:'book',color:'sand',body:'<h2>Kitap · Yazar</h2><p><br></p><h2>Aklımda kalan fikir</h2><p><br></p><h2>Alıntılar</h2><blockquote></blockquote><h2>Hayatıma nasıl uygularım?</h2><p><br></p>',tasks:[]},
{id:'ideas',title:'Fikir bahçesi',desc:'Aklına gelenleri yakala ve bağlantılar kur.',icon:'spark',color:'lavender',body:'<h2>Fikir</h2><p><br></p><h2>Neden değerli?</h2><p><br></p><h2>Bağlantılı düşünceler</h2><ul><li></li></ul><h2>Bir sonraki küçük adım</h2><p><br></p>',tasks:[]},
{id:'weekly',title:'Haftalık plan',desc:'Öncelikler, alışkanlıklar ve haftanın değerlendirmesi.',icon:'calendar',color:'sage',body:'<h2>Bu haftanın odağı</h2><p><br></p><h2>Üç önceliğim</h2><ol><li></li><li></li><li></li></ol><h2>Hafta sonu değerlendirmesi</h2><p><br></p>',tasks:['Pazartesi planı','Haftalık değerlendirme']},
{id:'shopping',title:'Alışveriş listesi',desc:'İhtiyaçları yaz, aldıklarını işaretle.',icon:'tasks',color:'sand',body:'<h2>İhtiyaçlar</h2><p>Bütçe ve diğer notlar…</p>',tasks:['Sebze ve meyve','Temel ihtiyaçlar','Ev ürünleri']}
];
function welcomeScreen(){return `<div class="onboarding"><div class="brandmark">${icon('note')}</div><div class="eyebrow">DÜŞÜNCELERİNE BİR YER AÇ</div><h1>Sadie<span style="color:var(--brand);font-style:italic">Notes</span></h1><p>Küçük bir fikirden büyük planlara.<br>Her şeyin, sana ait sakin bir yerde.</p><div class="welcome-features"><div>${icon('edit')}<span><strong>Yaz, planla, hatırla.</strong><small>Notlar, görevler ve hatırlatıcılar bir arada.</small></span></div><div>${icon('folder')}<span><strong>Her düşünceye bir yer.</strong><small>Klasörler, etiketler ve güçlü arama.</small></span></div><div>${icon('lock')}<span><strong>Sana ait kalsın.</strong><small>Çevrimdışı kullanım, PIN ve parolalı yedek.</small></span></div></div><button class="primary" data-action="start">Kendi alanımı oluştur ${icon('plus')}</button><button class="secondary" data-action="restore" style="margin-top:12px;width:100%">Yedeğimden geri yükle</button><p class="small muted" style="margin-top:17px">Hesap yok. Reklam yok. İnternet izni yok.</p></div>`;}
const sections={all:['Tüm notlar','note'],favorites:['Favoriler','star'],pinned:['Sabitlenenler','pin'],tasks:['Görevler','tasks'],calendar:['Takvim','calendar'],reminders:['Hatırlatıcılar','bell'],templates:['Şablonlar','template'],archive:['Arşiv','archive'],trash:['Çöp kutusu','trash'],settings:['Ayarlar','settings']};
function sidebar(){const live=state.notes.filter(n=>!n.deletedAt&&!n.archived);const countFor=s=>s==='all'?live.length:s==='favorites'?live.filter(n=>n.favorite).length:s==='pinned'?live.filter(n=>n.pinned).length:s==='trash'?state.notes.filter(n=>n.deletedAt).length:s==='archive'?state.notes.filter(n=>n.archived&&!n.deletedAt).length:s==='tasks'?live.reduce((n,a)=>n+a.tasks.filter(t=>!t.done).length,0):s==='reminders'?live.filter(n=>n.reminder>Date.now()).length:null;return `<aside class="sidebar ${drawer?'open':''}"><div class="brand"><span class="brandmark">${icon('note')}</span><span>Sadie<em>Notes</em></span></div><button class="primary" data-action="new">${icon('plus')} Yeni not</button><nav class="nav-group">${Object.entries(sections).map(([s,[label,ico]])=>`<button class="nav-item ${section===s&&folder===null?'active':''}" data-section="${s}">${icon(ico)}${label}${countFor(s)!==null?`<span class="count">${countFor(s)}</span>`:''}</button>`).join('')}</nav><div><div class="side-label">KLASÖRLER <button data-action="new-folder" aria-label="Klasör oluştur">${icon('plus')}</button></div><div class="nav-group">${state.folders.map(f=>`<button class="nav-item ${folder===f.id?'active':''}" data-folder="${esc(f.id)}">${icon('folder')}<span>${esc(f.name)}</span><span class="count">${live.filter(n=>n.folder===f.id).length}</span></button>`).join('')}${state.folders.length?'':'<span class="small muted" style="padding:0 12px">Düşüncelerini düzenle.</span>'}</div></div><div class="side-footer">${icon('lock')} ${native?'Cihazında şifreli saklanır.':'Tarayıcı önizlemesi · yerel kayıt'}<br>SadieNotes 1.0.0</div></aside>`;}
function topbar(){return `<header class="topbar">${ib('menu','menu','Menüyü aç')}<div class="search-box">${icon('search')}<input id="search" type="search" placeholder="Notlarında bir şey bul…" aria-label="Notlarda ara" value="${esc(query)}"><kbd>Ctrl K</kbd></div>${ib('theme','moon','Temayı değiştir')}<button class="primary" data-action="new">${icon('plus')}<span class="new-label">Yeni not</span></button></header>`;}
function stats(){const live=state.notes.filter(n=>!n.deletedAt&&!n.archived),total=live.flatMap(n=>n.tasks),done=total.filter(t=>t.done).length;const week=live.filter(n=>n.created>Date.now()-7*86400000).length;return `<div class="stats"><div class="stat"><strong>${live.length}</strong><span>Biriken düşünce</span></div><div class="stat"><strong>${done}<span style="font-family:system-ui;font-size:14px"> / ${total.length}</span></strong><span>Tamamlanan görev</span></div><div class="stat"><strong>${new Set(live.flatMap(n=>n.tags)).size}</strong><span>Farklı etiket</span></div><div class="stat"><strong>${week}<span style="font-family:system-ui;font-size:14px"> / ${state.settings.weeklyGoal}</span></strong><span>Bu hafta yazdığın not</span><div class="meter"><span style="width:${Math.min(100,week/state.settings.weeklyGoal*100)}%"></span></div></div></div>`;}
function card(n){return `<article class="note-card ${n.color} ${selected.has(n.id)?'selected':''}" data-note="${esc(n.id)}" tabindex="0" role="button" aria-label="${esc(n.title||'Başlıksız not')}">${selecting?`<input class="select-note" type="checkbox" data-select="${esc(n.id)}" ${selected.has(n.id)?'checked':''} aria-label="Notu seç">`:''}<div class="card-top"><span>${esc(state.folders.find(f=>f.id===n.folder)?.name||'Kişisel alan')}</span><span class="row" style="gap:6px">${n.pinned?icon('pin'):''}${n.favorite?icon('star'):''}</span></div><h3>${esc(n.title||'Başlıksız not')}</h3><p class="note-excerpt">${esc(bodyText(n).slice(0,250)||n.tasks.map(t=>(t.done?'☑ ':'☐ ')+t.text).join('\n')||'Henüz yazılmamış bir sayfa…')}</p>${n.tags.length?`<div class="card-tags">${n.tags.slice(0,3).map(t=>`<span class="tag">#${esc(t)}</span>`).join('')}</div>`:''}<div class="card-bottom"><span>${date(n.updated,true)}</span><span class="spacer"></span>${n.tasks.length?`${icon('tasks')} ${n.tasks.filter(t=>t.done).length}/${n.tasks.length}`:''}${n.attachments.length?`${icon('clip')} ${n.attachments.length}`:''}${n.reminder?icon('bell'):''}</div></article>`;}
function filtered(){return C.filter(state.notes,{section,folder,tag,query,sort:state.settings.sort});}
function listContent(){const list=filtered(),tags=[...new Set(state.notes.filter(n=>!n.deletedAt).flatMap(n=>n.tags))].sort((a,b)=>a.localeCompare(b,'tr'));return `${section==='all'&&folder===null&&!query?stats():''}<div class="chips">${tags.length?`<button class="chip ${tag?'':'active'}" data-tag="">Tüm etiketler</button>`:''}${tags.slice(0,50).map(t=>`<button class="chip ${tag===t?'active':''}" data-tag="${esc(t)}">#${esc(t)}</button>`).join('')}</div><div class="section-row"><h2>${query?'Arama sonuçları':section==='all'?'Not defterin':sections[section]?.[0]||'Notlar'}</h2><span class="muted" id="list-count">${list.length}</span><div class="right"><select id="sort" aria-label="Notları sırala"><option value="updated" ${state.settings.sort==='updated'?'selected':''}>Son düzenlenen</option><option value="created" ${state.settings.sort==='created'?'selected':''}>Yeni oluşturulan</option><option value="title" ${state.settings.sort==='title'?'selected':''}>Başlık A–Z</option><option value="reminder" ${state.settings.sort==='reminder'?'selected':''}>Hatırlatıcı tarihi</option></select>${ib('view',state.settings.view==='grid'?'list':'grid','Görünümü değiştir')}${ib('select','check','Çoklu seçim',selecting)}</div></div>${section==='trash'?'<p class="small muted" style="margin-bottom:15px">Notlar sen kalıcı olarak silene kadar burada tutulur.</p>':''}${selecting?`<div class="selection-row"><span class="count">${selected.size} not seçildi</span><div class="batch-actions"><button class="secondary" data-action="select-all">Tümünü seç</button>${section==='trash'?'<button class="secondary" data-action="batch-restore">Geri yükle</button><button class="secondary" data-action="batch-purge">Kalıcı sil</button>':'<button class="secondary" data-action="batch-folder">Taşı</button><button class="secondary" data-action="batch-archive">Arşivle</button><button class="secondary" data-action="batch-trash">Sil</button>'}</div></div>`:''}<div class="notes-grid ${state.settings.view}" id="notes-list">${list.length?list.map(card).join(''):empty(query?'Sonuç bulunamadı.':'Yeni bir sayfaya yer var.',query?'Başka bir sözcük veya etiket dene.':'Bir not yaz veya şablonlardan ilham al.')}</div>`;}
function empty(title,sub){return `<div class="empty">${icon('note')}<h3>${title}</h3><p>${sub}</p><button class="primary" data-action="new">${icon('plus')} Yeni not</button></div>`;}
function templatesContent(){return `<div class="template-grid">${templates.map(t=>`<button class="template-card" data-template="${t.id}">${icon(t.icon)}<h3>${t.title}</h3><p>${t.desc}</p></button>`).join('')}</div>`;}
function taskRow(n,t,global=false){return `<div class="task ${t.done?'done':''} ${t.priority}"><input type="checkbox" data-task-check="${esc(t.id)}" data-owner="${esc(n.id)}" ${t.done?'checked':''} aria-label="${esc(t.text)}"><div class="task-content"><div class="task-text">${esc(t.text)}</div><small>${global?`${esc(n.title||'Başlıksız not')} · `:''}${t.due?esc(t.due)+(t.due<dayKey(Date.now())&&!t.done?' · Gecikmiş':''):''}${t.priority==='high'?' · Yüksek öncelik':''}</small></div><button class="icon-button" data-task-edit="${esc(t.id)}" data-owner="${esc(n.id)}" aria-label="Görevi düzenle">${icon('edit')}</button>${!global?`<button class="icon-button" data-task-delete="${esc(t.id)}" aria-label="Görevi sil">${icon('close')}</button>`:`<button class="icon-button" data-note="${esc(n.id)}" aria-label="Notu aç">${icon('note')}</button>`}</div>`;}
function tasksContent(){let entries=state.notes.filter(n=>!n.deletedAt&&!n.archived).flatMap(n=>n.tasks.filter(t=>!query||[t.text,n.title,...n.tags].join(' ').toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))).map(t=>({n,t})));entries.sort((a,b)=>Number(a.t.done)-Number(b.t.done)||(a.t.due||'9999').localeCompare(b.t.due||'9999'));const pending=entries.filter(e=>!e.t.done),done=entries.filter(e=>e.t.done);return `<div class="panel"><div class="row spread"><h3>Bir adım daha.</h3><span class="small muted">${pending.length} açık · ${done.length} tamamlanan</span></div><p>Görevlerini notlarına ekle; hepsini buradan takip et.</p></div><h3>Açık görevler</h3><div class="tasks">${pending.map(e=>taskRow(e.n,e.t,true)).join('')||'<p class="muted small">Açık görev yok.</p>'}</div><details class="subsection"><summary class="small muted">Tamamlananlar (${done.length})</summary><div class="tasks">${done.map(e=>taskRow(e.n,e.t,true)).join('')}</div></details>`;}
function agendaEntries(){return state.notes.filter(n=>!n.deletedAt&&!n.archived).flatMap(n=>[...(n.reminder?[{note:n,id:n.id,date:dayKey(n.reminder),time:n.reminder,title:n.title||'Başlıksız not',type:'bell'}]:[]),...n.tasks.filter(t=>t.due&&!t.done).map(t=>({note:n,id:t.id,date:t.due,time:0,title:t.text,type:'tasks'}))]);}
function calendarContent(){const first=new Date(month.getFullYear(),month.getMonth(),1),days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),offset=(first.getDay()+6)%7,entries=agendaEntries();const chosen=entries.filter(e=>e.date===calendarDate);return `<div class="calendar-layout"><div class="panel"><div class="row spread">${ib('prev-month','back','Önceki ay')}<h3>${new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric'}).format(month)}</h3><button class="icon-button" data-action="next-month" aria-label="Sonraki ay" style="transform:rotate(180deg)">${icon('back')}</button></div><div class="calendar">${['Pt','Sa','Ça','Pe','Cu','Ct','Pa'].map(d=>`<span>${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const key=dayKey(new Date(month.getFullYear(),month.getMonth(),i+1));return `<button data-day="${key}" class="${key===calendarDate?'active':''} ${key===dayKey(Date.now())?'today':''}">${i+1}${entries.some(e=>e.date===key)?'<i class="day-dot"></i>':''}</button>`}).join('')}</div><button class="secondary" data-action="today">Bugüne dön</button></div><div class="panel"><h3>${date(new Date(calendarDate+'T12:00:00').getTime(),true)}</h3><p>Not hatırlatıcıların ve görev bitiş tarihlerin.</p>${chosen.map(e=>`<button class="agenda-entry" data-note="${esc(e.note.id)}">${icon(e.type)}<span><strong>${esc(e.title)}</strong><small>${e.time?date(e.time):'Gün boyu'} · ${esc(e.note.title||'Başlıksız not')}</small></span></button>`).join('')||'<p class="small muted" style="margin-top:20px">Bugün için planlanmış bir şey yok.</p>'}</div></div>`;}
function settingsContent(){const st=nativeStatus();return `<div class="settings-grid"><section class="panel"><h3>Görünüm</h3><p>Yazma alanını kendine göre ayarla.</p><label class="field"><span>Tema</span><select id="setting-theme">${[['light','Aydınlık'],['dark','Karanlık'],['system','Sistem']].map(([v,l])=>`<option value="${v}" ${state.settings.theme===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Yazı boyutu · ${state.settings.fontSize} px</span><input id="setting-size" type="range" min="14" max="26" value="${state.settings.fontSize}"></label><label class="field"><span>Yazı tipi</span><select id="setting-font"><option value="sans" ${state.settings.font==='sans'?'selected':''}>Sade</option><option value="serif" ${state.settings.font==='serif'?'selected':''}>Kitap</option></select></label><label class="row small"><input type="checkbox" id="setting-spell" ${state.settings.spellcheck?'checked':''}> Yazım denetimi</label></section><section class="panel"><h3>Güvenlik</h3><p>${native?'Notların ve eklerin Android Keystore anahtarıyla AES-GCM kullanılarak cihazda şifreli saklanır.':'Tarayıcı önizlemesindeki veriler localStorage içinde şifresiz saklanır. Android APK cihazda şifreli saklama sağlar.'}</p><div class="actions"><button class="secondary" data-action="set-pin">${icon('lock')} ${st.pin?'PIN değiştir':'PIN oluştur'}</button>${st.pin?'<button class="secondary" data-action="remove-pin">PIN kaldır</button><button class="secondary" data-action="lock">Şimdi kilitle</button>':''}</div><p class="small" style="margin-top:14px">PIN kurtarma yoktur. Önemli notların için ayrıca yedek al.</p></section><section class="panel"><h3>Yedek ve aktarım</h3><p>Notları, görevleri, klasörleri, etiketleri ve ekleri birlikte yedekle. İstersen yedeğine parola koy.</p><div class="actions"><button class="primary" data-action="backup">${icon('download')} Yedek al</button><button class="secondary" data-action="restore">${icon('upload')} Geri yükle</button><button class="secondary" data-action="import-text">Metin / Markdown al</button></div><p class="small" style="margin-top:13px">Geri yükleme mevcut verinin yerini alır. Önce yedek alman önerilir.</p></section><section class="panel"><h3>Klasörler ve alışkanlıklar</h3><label class="field"><span>Yeni notların klasörü</span><select id="setting-folder"><option value="">Klasörsüz</option>${state.folders.map(f=>`<option value="${esc(f.id)}" ${state.settings.defaultFolder===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label><label class="field"><span>Haftalık not hedefi</span><input id="setting-goal" type="number" min="1" max="100" value="${state.settings.weeklyGoal}"></label><button class="secondary" data-action="manage-folders">Klasörleri yönet</button></section><section class="panel"><h3>Hatırlatıcılar</h3><p>Notun içinden tarih ve saat seç. Android bildirim izni gerekir. Pil tasarrufu ve sistem koşulları bildirimi geciktirebilir; kesin zamanlı alarm değildir.</p><p class="small" style="margin-top:12px">Bildirimlerde not içeriği gösterilmez. ${native?(st.notifications?'Bildirim izni açık.':'İlk hatırlatıcıda bildirim izni sorulur.'):'Tarayıcıda sistem bildirimi planlanmaz.'}</p></section><section class="panel"><h3>SadieNotes 1.0.0</h3><p>Sana ait bir düşünce alanı. Türkçe arayüz, çevrimdışı çalışma ve dışa aktarılabilir veriler.</p><p class="small" style="margin-top:12px">Ctrl N: yeni not · Ctrl K: arama · Ctrl S: kaydet · Esc: geri. Bulut eşitleme ve ortak düzenleme bu sürümde bulunmaz.</p><button class="secondary" data-action="about" style="margin-top:14px">Özellikler ve sınırlar</button></section></div>`;}
function renderLibrary(){const title=folder!==null?state.folders.find(f=>f.id===folder)?.name||'Klasör':sections[section]?.[0]||'Tüm notlar';const desc={all:'Zihnini boşalt. Fikirlerine, planlarına ve küçük anlarına yer aç.',templates:'Boş sayfayı atla. İhtiyacına uygun bir başlangıç seç.',tasks:'Büyük planlar, küçük adımlarla ilerler.',calendar:'Zamanı gelen düşüncelerine bir göz at.',settings:'Bu alanı kendine göre düzenle.',trash:'Silinen notlarını geri alabilir veya kalıcı olarak silebilirsin.',archive:'Şimdilik kenara ayırdığın düşünceler.',reminders:'Zamanı geldiğinde yeniden dönmek istediğin notlar.'};$('#app').innerHTML=`<div class="app-shell">${sidebar()}<main class="content">${topbar()}<div class="hero"><div><div class="eyebrow">KENDİNE AİT BİR ALAN</div><h1>${section==='all'&&folder===null?'Merhaba, iyi ki yazıyorsun.':esc(title)}</h1><p>${desc[section]||'Tekrar dönmek istediğin düşüncelerin burada.'}</p></div><div class="hero-art">${icon(sections[section]?.[1]||'folder')}</div></div><div id="library-body">${section==='templates'?templatesContent():section==='tasks'?tasksContent():section==='calendar'?calendarContent():section==='settings'?settingsContent():listContent()}</div><p class="key-hint">${native?'Notların cihazında kalır. Her değişiklik otomatik kaydedilir.':'Tarayıcı önizlemesi · Veriler bu tarayıcıda saklanır.'}</p></main></div>`;$('.topbar .icon-button').classList.add('mobile-menu');}
function toolbar(){return `<div class="toolbar" aria-label="Metin biçimlendirme"><button data-cmd="undo" aria-label="Geri al">↶</button><button data-cmd="redo" aria-label="Yinele">↷</button><span class="sep"></span><select id="format-block" aria-label="Paragraf biçimi"><option value="p">Paragraf</option><option value="h1">Başlık 1</option><option value="h2">Başlık 2</option><option value="h3">Başlık 3</option><option value="blockquote">Alıntı</option><option value="pre">Kod bloğu</option></select><button data-cmd="bold" aria-label="Kalın"><b>B</b></button><button data-cmd="italic" aria-label="İtalik"><i>İ</i></button><button data-cmd="underline" aria-label="Altı çizili"><u>U</u></button><button data-cmd="strikeThrough" aria-label="Üstü çizili"><s>S</s></button><span class="sep"></span><button data-cmd="insertUnorderedList" aria-label="Madde listesi">• ≡</button><button data-cmd="insertOrderedList" aria-label="Numaralı liste">1 ≡</button><button data-action="insert-link" aria-label="Bağlantı ekle">${icon('clip')}</button><button data-action="insert-table" aria-label="Tablo ekle">${icon('grid')}</button><button data-cmd="insertHorizontalRule" aria-label="Ayırıcı ekle">―</button><button data-cmd="removeFormat" aria-label="Biçimi temizle">Tx</button></div>`;}
function renderEditor(){const n=note();if(!n){currentId='';render();return;}if(n.deletedAt){$('#app').innerHTML=`<div class="editor-shell"><header class="editor-header">${ib('back','back','Geri')}<span>Çöp kutusu</span></header><div class="editor-locked"><h1>${esc(n.title||'Başlıksız not')}</h1><p>Bu not çöp kutusunda. Düzenlemek için önce geri yükle.</p><div class="actions" style="justify-content:center"><button class="primary" data-action="restore-note">Geri yükle</button><button class="danger" data-action="purge-note">Kalıcı sil</button></div></div></div>`;return;}const tasks=n.tasks.filter(t=>t.done).length;$('#app').innerHTML=`<div class="editor-shell"><header class="editor-header">${ib('back','back','Notlara dön')}<span class="brand editor-brand" style="font-size:21px">Sadie<em>Notes</em></span><span id="save-status" class="save-status">Kaydedildi</span>${ib('pin','pin','Sabitle',n.pinned)}${ib('favorite','star','Favori',n.favorite)}${ib('note-menu','more','Not seçenekleri')}</header><main class="editor-wrapper"><input id="note-title" class="editor-title" placeholder="Başlıksız bir düşünce…" aria-label="Not başlığı" maxlength="500" value="${esc(n.title)}"><div class="meta-row"><select id="note-folder" aria-label="Not klasörü"><option value="">Klasörsüz</option>${state.folders.map(f=>`<option value="${esc(f.id)}" ${n.folder===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select><span>${date(n.created,true)}</span><span>·</span><span>${n.mode==='markdown'?'Markdown':'Zengin metin'}</span><button data-action="reminder" class="chip">${n.reminder?'◷ '+date(n.reminder):'+ Hatırlatıcı'}</button></div><div class="row" style="flex-wrap:wrap;gap:9px;margin-bottom:20px">${C.themes.map(c=>`<button class="color-dot ${c===n.color?'active':''}" data-color="${c}" aria-label="${c} not rengi" style="background:var(--${c==='plain'?'surface':c})"></button>`).join('')}<button class="chip" data-action="edit-tags">${icon('tag')} Etiketler</button>${n.tags.map(t=>`<span class="tag">#${esc(t)}</span>`).join('')}</div>${n.mode==='rich'?toolbar():`<div class="editor-tabs"><button class="${!modePreview?'active':''}" data-action="md-edit">Yaz</button><button class="${modePreview?'active':''}" data-action="md-preview">Önizle</button><button data-action="markdown-help">Sözdizimi</button></div>`}<div style="font-family:${state.settings.font==='serif'?'Georgia,serif':'inherit'}">${n.mode==='rich'?`<div id="editor" class="editor-body" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Not içeriği" spellcheck="${state.settings.spellcheck}" data-placeholder="Aklından geçenleri buraya bırak…">${C.sanitize(n.body)}</div>`:modePreview?`<div class="markdown-preview">${C.markdown(n.body)}</div>`:`<textarea id="markdown" class="markdown-source" placeholder="# İlk düşüncem" aria-label="Markdown içeriği" spellcheck="${state.settings.spellcheck}">${esc(n.body)}</textarea>`}</div><footer class="editor-footer"><span id="word-count"></span><span>Otomatik kayıt açık · ${date(n.updated,true)}</span></footer><section class="subsection"><div class="row spread"><h3>Görevler <span class="muted">${tasks}/${n.tasks.length}</span></h3><button class="chip" data-action="clear-completed">Tamamlananları temizle</button></div><div class="tasks">${n.tasks.map(t=>taskRow(n,t)).join('')}</div><form id="task-form" class="task-add"><input id="new-task" placeholder="Küçük bir sonraki adım…" aria-label="Yeni görev" maxlength="2000"><button class="primary" type="submit" aria-label="Görev ekle">${icon('plus')}</button></form></section><section class="subsection"><div class="row spread"><h3>Dosyalar ve görseller</h3><button class="chip" data-action="attach">${icon('plus')} Ek ekle</button></div><p class="small muted" style="margin-top:9px">Dosya başına en fazla 20 MB. Ekler Android APK içinde cihazda şifreli saklanır.</p><div id="attachments">${n.attachments.map(a=>`<div class="attachment"><span id="thumb-${a.id}">${icon('clip')}</span><div class="file-info"><strong>${esc(a.name)}</strong><small>${(a.size/1024).toFixed(1)} KB · ${esc(a.mime)}</small></div><button class="icon-button" data-file-open="${a.id}" aria-label="Eki aç">${icon('download')}</button><button class="icon-button" data-file-remove="${a.id}" aria-label="Eki kaldır">${icon('close')}</button></div>`).join('')}</div></section></main></div>`;wordCount();if(native)for(const a of n.attachments.filter(a=>['image/png','image/jpeg','image/webp','image/gif'].includes(a.mime)&&a.size<5*1024*1024).slice(0,6)){const b64=Native.attachmentData(a.id);if(b64){const el=$('#thumb-'+a.id);if(el)el.innerHTML=`<img class="thumb" alt="${esc(a.name)}" src="data:${a.mime};base64,${b64}">`;}}}
function wordCount(){const n=note();if(!n||!$('#word-count'))return;const txt=bodyText(n),words=txt.trim()?txt.trim().split(/\s+/).length:0;$('#word-count').textContent=`${words} kelime · ${txt.length} karakter · ${Math.max(1,Math.ceil(words/200))} dk okuma`;}
function render(){colors();if(fatal){$('#app').innerHTML=`<div class="editor-locked"><h1>Veri okunamadı.</h1><p>${esc(fatal)}</p><p>Mevcut verinin üzerine yazılmadı.</p><button class="primary" data-action="restore">Yedekten geri yükle</button></div>`;return;}if(welcome){$('#app').innerHTML=welcomeScreen();return;}if(currentId)renderEditor();else renderLibrary();}
function modal(title,body,actions='<button class="secondary" data-action="close-modal">Kapat</button>'){savedRange=selectionRange();$('#overlay').innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${body}<div class="modal-actions">${actions}</div></section>`;const focus=$('#overlay input:not([type=checkbox]),#overlay select,#overlay textarea,#overlay button');if(focus)setTimeout(()=>focus.focus(),50);}
function closeModal(){$('#overlay').innerHTML='';const ed=$('#editor');if(ed&&savedRange){try{ed.focus();getSelection().removeAllRanges();getSelection().addRange(savedRange);}catch(e){}}}
let confirmCallback=null,savedRange=null;
function confirmBox(title,body,callback,label='Onayla',danger=false){confirmCallback=callback;modal(title,`<p>${body}</p>`,`<button class="secondary" data-action="close-modal">Vazgeç</button><button class="${danger?'danger':'primary'}" data-action="confirm">${label}</button>`);}
function inputModal(title,label,value,action,type='text',extra=''){modal(title,`<label class="field"><span>${label}</span><input id="modal-value" type="${type}" value="${esc(value)}"></label>${extra}`,`<button class="secondary" data-action="close-modal">Vazgeç</button><button class="primary" data-action="${action}">Kaydet</button>`);}
function selectionRange(){try{const s=getSelection();if(s.rangeCount&&$('#editor')?.contains(s.anchorNode))return s.getRangeAt(0).cloneRange();}catch(e){}return null;}
function command(name,value=null){if(!$('#editor'))return;remember();$('#editor').focus();document.execCommand(name,false,value);note().body=C.sanitize($('#editor').innerHTML);touch();wordCount();}
function cleanup(){if(native){const ids=state.notes.flatMap(n=>n.attachments.map(a=>a.id));Native.pruneAttachments(JSON.stringify(ids));}}
function moveToTrash(n){n.deletedAt=Date.now();n.reminder=0;}
function updateLibrary(){if(currentId)return;const el=$('#library-body');if(el)el.innerHTML=section==='tasks'?tasksContent():listContent();}
function noteMenu(){const n=note();modal('Not seçenekleri',`<div class="menu-options"><button data-action="duplicate">${icon('copy')} Kopyasını oluştur</button><button data-action="change-mode">${icon('edit')} ${n.mode==='rich'?'Markdown’a geçir':'Zengin metne geçir'}</button><button data-action="reminder">${icon('bell')} Hatırlatıcı ayarla</button><button data-action="history">${icon('clock')} Sürüm geçmişi (${n.history.length})</button><button data-action="export-note">${icon('download')} Dışa aktar</button><button data-action="share-note">${icon('share')} Paylaş</button><button data-action="print-note">${icon('print')} PDF / Yazdır</button><button data-action="archive-note">${icon('archive')} ${n.archived?'Arşivden çıkar':'Arşivle'}</button><button class="danger-text" data-action="trash-note">${icon('trash')} Çöp kutusuna taşı</button></div>`);}
function backupModal(restore=false){modal(restore?'Yedeği geri yükle':'Yedeğini yanında taşı',`<p>${restore?'SadieNotes yedeğini seç. Parolalıysa yedek parolasını gir. Mevcut notların yerine yedek yüklenecek.':'Notlar, klasörler, görevler ve ekler birlikte yedeklenir. Bir parola girersen yedek dosyan AES-GCM ile şifrelenir.'}</p><label class="field"><span>${restore?'Yedek parolası (varsa)':'Yedek parolası (isteğe bağlı)'}</span><input id="backup-password" type="password" autocomplete="off" placeholder="${restore?'Parolasızsa boş bırak':'En az 8 karakter veya boş'}"></label>${restore?'':'<p class="small muted">Parolanı unutursan şifreli yedeği açamazsın. Parolasız yedek okunabilir metin içerir.</p>'}`,`<button class="secondary" data-action="close-modal">Vazgeç</button><button class="primary" data-action="${restore?'do-restore':'do-backup'}">${restore?'Dosya seç':'Yedek oluştur'}</button>`);}
function download(name,mime,raw){if(native){Native.exportText(name,mime,raw);return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([raw],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportNote(format){const n=note(),name=(n.title||'SadieNotes').replace(/[\\/:*?"<>|]/g,'_').slice(0,100);const html=n.mode==='markdown'?C.markdown(n.body):C.sanitize(n.body),taskText=n.tasks.map(t=>`- [${t.done?'x':' '}] ${t.text}`).join('\n');if(format==='html')download(name+'.html','text/html',printHTML(n));else if(format==='json')download(name+'.json','application/json',JSON.stringify({format:'SadieNotesNote',version:1,note:n},null,2));else download(name+(format==='md'?'.md':'.txt'),format==='md'?'text/markdown':'text/plain',(format==='md'?'# ':'')+(n.title||'Başlıksız not')+'\n\n'+(format==='md'&&n.mode==='markdown'?n.body:C.text(html))+(taskText?'\n\n'+taskText:''));closeModal();}
function printHTML(n){return '<!doctype html><html lang="tr"><meta charset="utf-8"><title>'+esc(n.title)+'</title><style>body{font:16px/1.7 sans-serif;padding:25px;color:#222}h1{font-size:30px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:8px}pre{white-space:pre-wrap}blockquote{border-left:3px solid #782c43;padding-left:15px}</style><h1>'+esc(n.title||'Başlıksız not')+'</h1>'+(n.mode==='markdown'?C.markdown(n.body):C.sanitize(n.body))+(n.tasks.length?'<h2>Görevler</h2><ul>'+n.tasks.map(t=>'<li>'+(t.done?'☑ ':'☐ ')+esc(t.text)+'</li>').join('')+'</ul>':'')+(n.tags.length?'<p>Etiketler: '+n.tags.map(esc).join(', ')+'</p>':'')+'</html>';}
function browserImport(kind){const el=document.createElement('input');el.type='file';el.accept=kind==='backup'?'.json,.snb':'.txt,.md,.markdown,.json';el.onchange=async()=>{const f=el.files[0];if(!f)return;if(f.size>12*1024*1024){toast('Dosya 12 MB sınırını aşıyor.');return;}try{const raw=await f.text();if(kind==='backup'){const obj=JSON.parse(raw);if(obj.format!=='SadieNotesBackup')throw Error('Tarayıcıda yalnızca parolasız yedek açılır. Şifreli yedek için APK kullan.');window.onBackupImport(obj.data);}else window.onTextImport(f.name,raw);}catch(e){toast(e.message);}};el.click();}
function editTask(id,owner){const n=state.notes.find(n=>n.id===owner),t=n?.tasks.find(t=>t.id===id);if(!t)return;modal('Görevi düzenle',`<label class="field"><span>Görev</span><input id="task-text" maxlength="2000" value="${esc(t.text)}"></label><label class="field"><span>Bitiş tarihi (isteğe bağlı)</span><input id="task-due" type="date" value="${esc(t.due)}"></label><label class="field"><span>Öncelik</span><select id="task-priority">${[['low','Düşük'],['normal','Normal'],['high','Yüksek']].map(([v,l])=>`<option value="${v}" ${t.priority===v?'selected':''}>${l}</option>`).join('')}</select></label>`,`<button class="secondary" data-action="close-modal">Vazgeç</button><button class="primary" data-save-task="${esc(id)}" data-owner="${esc(owner)}">Kaydet</button>`);}
const actions={
start(){welcome=false;if(!state.notes.length){state.notes.push(C.makeNote({title:'SadieNotes’a hoş geldin',color:'rose',tags:['başlangıç'],body:'<h2>Burada düşüncelerine yer var.</h2><p>Bu notu düzenleyerek başlayabilir veya kendi boş sayfanı açabilirsin.</p><p><strong>Not seçenekleri</strong> menüsünde dışa aktarma, sürüm geçmişi, hatırlatıcı ve daha fazlası var.</p><p>Klasörler ve etiketler düzeni korur. Görevler küçük adımları takip eder.</p><blockquote>Yazmak, kendine ayırdığın küçük bir zaman.</blockquote>',tasks:[{id:C.uid(),text:'İlk düşüncemi yaz',done:false,due:'',priority:'normal'},{id:C.uid(),text:'Ayarlar’dan yedeğimi al',done:false,due:'',priority:'normal'}]}));}persist();render();},
new(){newNote();},menu(){drawer=!drawer;render();},back(){currentId='';persist();render();},theme(){state.settings.theme=document.body.classList.contains('dark')?'light':'dark';persist();colors();},view(){state.settings.view=state.settings.view==='grid'?'list':'grid';persist();updateLibrary();},select(){selecting=!selecting;selected.clear();updateLibrary();},'select-all'(){filtered().forEach(n=>selected.add(n.id));updateLibrary();},'close-modal':closeModal,confirm(){const cb=confirmCallback;confirmCallback=null;closeModal();if(cb)cb();},
'new-folder'(){inputModal('Yeni klasör','Klasör adı','','save-folder');},'save-folder'(){const name=$('#modal-value').value.trim().slice(0,80);if(!name)return toast('Klasör adını yaz.');if(state.folders.some(f=>f.name.toLocaleLowerCase('tr')===name.toLocaleLowerCase('tr')))return toast('Bu adla bir klasör var.');state.folders.push({id:C.uid(),name});persist();closeModal();render();},
'manage-folders'(){modal('Klasörleri yönet',`<p>Klasörü silmek notlarını silmez; notlar klasörsüz alana taşınır.</p>${state.folders.map(f=>`<div class="folder-manager"><strong>${esc(f.name)}</strong><button class="icon-button" data-folder-rename="${esc(f.id)}" aria-label="Yeniden adlandır">${icon('edit')}</button><button class="icon-button" data-folder-delete="${esc(f.id)}" aria-label="Klasörü sil">${icon('trash')}</button></div>`).join('')||'<p>Henüz klasör yok.</p>'}<button class="secondary" data-action="new-folder" style="margin-top:15px">Yeni klasör</button>`);},
pin(){note().pinned=!note().pinned;touch();render();},favorite(){note().favorite=!note().favorite;touch();render();},'note-menu':noteMenu,
'edit-tags'(){inputModal('Etiketler','Virgülle ayır',note().tags.join(', '),'save-tags','text','<p class="small muted">En fazla 30 etiket; etiket başına 40 karakter.</p>');},'save-tags'(){note().tags=[...new Set($('#modal-value').value.split(',').map(t=>t.trim().replace(/^#/, '').slice(0,40)).filter(Boolean))].slice(0,30);touch();closeModal();render();},
reminder(){const n=note(),v=n.reminder?new Date(n.reminder-new Date(n.reminder).getTimezoneOffset()*60000).toISOString().slice(0,16):'';inputModal('Not hatırlatıcısı','Tarih ve saat',v,'save-reminder','datetime-local','<p class="small muted">Android bildirim izni gerekir. Sistem, bildirimi pil koşullarına göre geciktirebilir.</p><button class="secondary" data-action="remove-reminder" style="margin-top:12px">Hatırlatıcıyı kaldır</button>');},'save-reminder'(){const time=new Date($('#modal-value').value).getTime();if(!Number.isFinite(time)||time<=Date.now())return toast('Gelecekte bir tarih ve saat seç.');note().reminder=time;touch();syncReminders();closeModal();render();toast(native?'Hatırlatıcı kaydedildi.':'Tarih kaydedildi; tarayıcıda bildirim planlanmaz.');},'remove-reminder'(){note().reminder=0;touch();syncReminders();closeModal();render();},
'archive-note'(){note().archived=!note().archived;touch();syncReminders();closeModal();currentId='';render();},'trash-note'(){confirmBox('Not çöp kutusuna taşınsın mı?','İstediğin zaman geri yükleyebilirsin.',()=>{moveToTrash(note());persist();syncReminders();currentId='';render();},'Çöp kutusuna taşı');},'restore-note'(){note().deletedAt=0;touch();render();},'purge-note'(){confirmBox('Not kalıcı olarak silinsin mi?','Bu not ve ekleri silinecek. Bu işlem geri alınamaz.',()=>{state.notes=state.notes.filter(n=>n.id!==currentId);if(persist()){currentId='';cleanup();render();}},'Kalıcı sil',true);},
duplicate(){const copy=JSON.parse(JSON.stringify(note()));copy.id=C.uid();copy.title=(copy.title||'Başlıksız not')+' (kopya)';copy.created=copy.updated=Date.now();copy.reminder=0;copy.history=[];copy.tasks.forEach(t=>t.id=C.uid());state.notes.unshift(copy);persist();closeModal();openNote(copy.id);},
'change-mode'(){confirmBox('Düzenleyiciyi değiştir','Zengin metinden Markdown’a geçişte metin korunur, biçimlendirme sadeleşir. Mevcut sürüm geçmişe kaydedilir.',()=>{remember();const n=note();if(n.mode==='rich'){n.body=C.text(n.body);n.mode='markdown';}else{n.body=C.markdown(n.body);n.mode='rich';}touch();render();},'Değiştir');},'md-edit'(){modePreview=false;render();},'md-preview'(){modePreview=true;render();},'markdown-help'(){modal('Markdown kısa rehberi','<p># Başlık 1<br>## Başlık 2<br>**Kalın** · *İtalik* · ~~Üstü çizili~~<br>- Madde<br>1. Sıralı madde<br>&gt; Alıntı<br>`kod`<br>``` ile çevrili kod bloğu<br>[Bağlantı](https://example.com)</p>');},
'insert-link'(){inputModal('Bağlantı ekle','https:// ile başlayan adres','','save-link','url');},'save-link'(){const url=$('#modal-value').value.trim();if(!/^https?:\/\//i.test(url))return toast('Geçerli bir https:// veya http:// adresi yaz.');closeModal();command('insertHTML',`<a href="${esc(url)}">${esc(url)}</a>`);},'insert-table'(){command('insertHTML','<table><tbody><tr><th>Başlık</th><th>Başlık</th></tr><tr><td>İçerik</td><td>İçerik</td></tr><tr><td><br></td><td><br></td></tr></tbody></table><p><br></p>');},
'clear-completed'(){if(!note().tasks.some(t=>t.done))return;confirmBox('Tamamlanan görevler temizlensin mi?','Bu nottaki tamamlanan görevler kaldırılacak.',()=>{note().tasks=note().tasks.filter(t=>!t.done);touch();render();},'Temizle');},
attach(){if(native)Native.pickAttachment(currentId);else toast('Dosya ekleme ve şifreli ek saklama Android APK içinde kullanılabilir.');},
history(){const n=note();modal('Sürüm geçmişi',`<p>Son 10 düzenleme oturumunun başlangıç metni saklanır. Görevler ve ekler bu geçmişin kapsamında değildir.</p>${n.history.slice().reverse().map((h,i)=>`<div class="history-item"><strong class="small">${date(h.time)}</strong><p>${esc(h.title||'Başlıksız')} · ${esc(C.text(h.mode==='markdown'?C.markdown(h.body):h.body).slice(0,100))}</p><button class="secondary" data-history="${n.history.length-1-i}">Bu metne dön</button></div>`).join('')||'<p>Henüz eski sürüm yok.</p>'}`);},
'export-note'(){modal('Notu dışa aktar','<p>Dosya ekleri ayrı tutulur. Ekleri de taşımak için tam yedek al.</p><div class="menu-options"><button data-export="txt">Düz metin (.txt)</button><button data-export="md">Markdown (.md)</button><button data-export="html">Biçimlendirilmiş HTML (.html)</button><button data-export="json">Not verisi (.json)</button></div>');},'share-note'(){const n=note(),txt=(n.title||'')+'\n\n'+bodyText(n)+'\n'+n.tasks.map(t=>(t.done?'☑ ':'☐ ')+t.text).join('\n');if(native)Native.share(n.title,txt);else if(navigator.clipboard)navigator.clipboard.writeText(txt).then(()=>toast('Not panoya kopyalandı.')).catch(()=>toast('Panoya erişilemedi. Dışa aktarmayı kullan.'));else toast('Paylaşmak için dışa aktarmayı kullan.');closeModal();},'print-note'(){if(native)Native.print(note().title||'SadieNotes',printHTML(note()));else{const w=window.open('','_blank');if(w){w.document.write(printHTML(note()));w.document.close();w.print();}else toast('Yazdırma penceresi engellendi. HTML olarak dışa aktarabilirsin.');}closeModal();},
backup(){if(!persist())return;backupModal(false);},restore(){backupModal(true);},'do-backup'(){const password=$('#backup-password').value;if(password&&password.length<8)return toast('Parola en az 8 karakter olmalı.');if(native)Native.exportBackup(password);else if(password)return toast('Parolalı yedek oluşturmak için Android APK kullan.');else download('SadieNotes-backup.json','application/json',JSON.stringify({format:'SadieNotesBackup',version:1,data:state,files:{}},null,2));closeModal();toast('Yedek hazırlanıyor.');},'do-restore'(){const p=$('#backup-password').value;closeModal();if(native)Native.importFile('backup',p);else browserImport('backup');},'import-text'(){if(native)Native.importFile('text','');else browserImport('text');},
'set-pin'(){if(native)Native.setPin();else toast('PIN ve cihaz şifrelemesi Android APK içinde kullanılabilir.');},'remove-pin'(){if(native)Native.removePin();},lock(){if(native)Native.lock();else toast('Uygulama kilidi Android APK içinde kullanılabilir.');},
'prev-month'(){month=new Date(month.getFullYear(),month.getMonth()-1,1);render();},'next-month'(){month=new Date(month.getFullYear(),month.getMonth()+1,1);render();},today(){month=new Date();calendarDate=dayKey(Date.now());render();},
'batch-folder'(){if(!selected.size)return toast('Önce not seç.');modal('Seçilen notları taşı',`<select id="batch-folder" class="full"><option value="">Klasörsüz</option>${state.folders.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select>`,`<button class="secondary" data-action="close-modal">Vazgeç</button><button class="primary" data-action="batch-move">Taşı</button>`);},'batch-move'(){const f=$('#batch-folder').value;state.notes.filter(n=>selected.has(n.id)).forEach(n=>{n.folder=f;n.updated=Date.now();});persist();closeModal();selected.clear();render();},'batch-archive'(){batch('archive');},'batch-trash'(){batch('trash');},'batch-restore'(){batch('restore');},'batch-purge'(){batch('purge');},
about(){modal('SadieNotes’ta neler var?','<p>Zengin metin, başlık, alıntı, kod, tablo, Markdown, renkler, klasörler, etiketler, favoriler, sabitleme, arşiv, çöp kutusu, toplu işlemler, görev ve öncelik, takvim, hatırlatıcı, dosya/görsel eki, sürüm geçmişi, şablonlar, arama, istatistik, tema ve yazı ayarları, PIN, şifreli cihaz kaydı, parolalı yedek, metin/HTML/Markdown/JSON aktarımı, paylaşma ve PDF yazdırma.</p><p style="margin-top:15px">Bu sürümde bulut eşitleme, ortak düzenleme, el yazısı/OCR ve ses kaydı yoktur. Mevcut ses dosyaları eklenebilir. Veri boyutu 12 MB, ek başına 20 MB, tam yedekte ek toplamı 40 MB sınırı vardır. Hatırlatıcılar kesin zaman garantisi vermez.</p>');}
};
function batch(kind){if(!selected.size)return toast('Önce not seç.');const run=()=>{if(kind==='purge')state.notes=state.notes.filter(n=>!selected.has(n.id));else for(const n of state.notes.filter(n=>selected.has(n.id))){if(kind==='trash')moveToTrash(n);if(kind==='archive')n.archived=true;if(kind==='restore')n.deletedAt=0;n.updated=Date.now();}if(persist()){syncReminders();if(kind==='purge')cleanup();selected.clear();render();}};if(kind==='purge')confirmBox('Seçili notlar kalıcı silinsin mi?','Notlar ve yalnızca onlara ait ekler kalıcı olarak silinir. Geri alınamaz.',run,'Kalıcı sil',true);else run();}
function escapeBack(){if($('#overlay').innerHTML){closeModal();return true;}if(currentId){actions.back();return true;}if(drawer){drawer=false;render();return true;}if(section!=='all'||folder!==null||query||tag){section='all';folder=null;query='';tag='';render();return true;}return false;}
window.appBack=escapeBack;window.onSecurityChanged=()=>{if(section==='settings')render();};window.openNotification=id=>{if(state.notes.some(n=>n.id===id&&!n.deletedAt))openNote(id);};
window.onAttachment=(id,a)=>{const n=state.notes.find(n=>n.id===id);if(!n||n.deletedAt)return toast('Ek hedefi bulunamadı.');try{const checked=C.validate({version:1,notes:[C.makeNote({attachments:[a]})],folders:[]}).notes[0].attachments[0];n.attachments.push(checked);n.updated=Date.now();persist();if(currentId===id)render();toast('Dosya eklendi.');}catch(e){toast('Ek bilgisi geçersiz.');}};
window.onTextImport=(name,raw)=>{try{if(raw.length>2000000)throw Error('Metin 2 milyon karakter sınırını aşıyor.');let n;if(/\.json$/i.test(name)){const obj=JSON.parse(raw);if(obj.format!=='SadieNotesNote'||!obj.note)throw Error('Not JSON biçimi geçersiz.');const data=C.validate({version:1,notes:[obj.note],folders:state.folders});n=data.notes[0];n.id=C.uid();n.attachments=[];n.history=[];n.reminder=0;n.deletedAt=0;n.archived=false;}else n=C.makeNote({title:name.replace(/\.[^.]+$/,''),body:raw,mode:'markdown',folder:state.settings.defaultFolder});n.created=n.updated=Date.now();state.notes.unshift(n);if(persist())openNote(n.id);}catch(e){toast(e.message);}};
window.onBackupImport=input=>{try{const next=C.validate(input);confirmBox('Yedek geri yüklensin mi?',`${next.notes.length} not ve ${next.folders.length} klasör bulundu. Mevcut notlarının yerini alacak.`,()=>{try{const raw=JSON.stringify(next);if(native){const error=Native.commitRestore(raw);if(error)throw Error(error);}else localStorage.setItem('sadienotes-data',raw);state=next;lastSaved=raw;fatal='';welcome=false;currentId='';section='all';folder=null;tag='';query='';selected.clear();syncReminders();cleanup();render();toast('Yedek geri yüklendi.');}catch(e){toast(e.message);}},'Geri yükle');}catch(e){toast('Yedek geçersiz: '+e.message);}};
document.addEventListener('click',e=>{if(e.target===$('#overlay')){closeModal();return;}const a=e.target.closest('a');if(a&&a.closest('#editor,.markdown-preview')){e.preventDefault();const url=a.getAttribute('href');if(url){if(native)Native.openLink(url);else window.open(url,'_blank','noopener');}return;}const b=e.target.closest('button,[data-note],[data-section],[data-folder],[data-select]');if(!b)return;if(b.dataset.select){e.stopPropagation();selected.has(b.dataset.select)?selected.delete(b.dataset.select):selected.add(b.dataset.select);updateLibrary();return;}if(b.dataset.note){if(selecting&&!currentId){selected.has(b.dataset.note)?selected.delete(b.dataset.note):selected.add(b.dataset.note);updateLibrary();}else openNote(b.dataset.note);return;}if(b.dataset.section){section=b.dataset.section;folder=null;tag='';query='';drawer=false;selected.clear();selecting=false;render();return;}if(b.hasAttribute('data-folder')){folder=b.dataset.folder;section='all';tag='';query='';drawer=false;render();return;}if(b.hasAttribute('data-tag')){tag=b.dataset.tag;updateLibrary();return;}if(b.dataset.template){newNote(b.dataset.template);return;}if(b.dataset.color){note().color=b.dataset.color;touch();render();return;}if(b.dataset.cmd){command(b.dataset.cmd);return;}if(b.dataset.action&&actions[b.dataset.action]){actions[b.dataset.action]();return;}if(b.dataset.taskCheck){return;}if(b.dataset.taskEdit){editTask(b.dataset.taskEdit,b.dataset.owner);return;}if(b.dataset.taskDelete){note().tasks=note().tasks.filter(t=>t.id!==b.dataset.taskDelete);touch();render();return;}if(b.dataset.saveTask){const n=state.notes.find(n=>n.id===b.dataset.owner),t=n.tasks.find(t=>t.id===b.dataset.saveTask),txt=$('#task-text').value.trim();if(!txt)return toast('Görev boş olamaz.');t.text=txt;t.due=$('#task-due').value;t.priority=$('#task-priority').value;n.updated=Date.now();persist();closeModal();render();return;}if(b.dataset.fileOpen){const a=note().attachments.find(a=>a.id===b.dataset.fileOpen);if(a&&native)Native.openAttachment(a.id,a.name,a.mime);return;}if(b.dataset.fileRemove){confirmBox('Ek kaldırılsın mı?','Bu nottan dosya bağlantısı kaldırılır.',()=>{note().attachments=note().attachments.filter(a=>a.id!==b.dataset.fileRemove);touch();cleanup();render();},'Kaldır');return;}if(b.dataset.export){exportNote(b.dataset.export);return;}if(b.hasAttribute('data-history')){const h=note().history[Number(b.dataset.history)];confirmBox('Bu metin sürümüne dönülsün mü?','Başlık ve metin değişir; görevler ve ekler korunur.',()=>{const n=note();const previous={time:n.updated,title:n.title,body:n.body,mode:n.mode};n.title=h.title;n.body=h.body;n.mode=h.mode;n.history.push(previous);n.history=n.history.slice(-10);historyCaptured=true;touch();render();},'Geri dön');return;}if(b.dataset.day){calendarDate=b.dataset.day;render();return;}if(b.dataset.folderDelete){const id=b.dataset.folderDelete;confirmBox('Klasör silinsin mi?','İçindeki notlar klasörsüz alana taşınacak.',()=>{state.folders=state.folders.filter(f=>f.id!==id);state.notes.filter(n=>n.folder===id).forEach(n=>n.folder='');if(state.settings.defaultFolder===id)state.settings.defaultFolder='';persist();render();},'Sil');return;}if(b.dataset.folderRename){const f=state.folders.find(f=>f.id===b.dataset.folderRename);inputModal('Klasörü yeniden adlandır','Yeni ad',f.name,'rename-folder');actions['rename-folder']=()=>{const value=$('#modal-value').value.trim().slice(0,80);if(!value)return;if(state.folders.some(x=>x.id!==f.id&&x.name.toLocaleLowerCase('tr')===value.toLocaleLowerCase('tr')))return toast('Bu adla bir klasör var.');f.name=value;persist();closeModal();render();};}});
document.addEventListener('input',e=>{const el=e.target,n=note();if(el.id==='search'){query=el.value;if(['tasks','all','favorites','pinned','reminders','archive','trash'].includes(section))updateLibrary();else{section='all';folder=null;const v=el.value;render();$('#search').focus();$('#search').setSelectionRange(v.length,v.length);}return;}if(el.id==='note-title'){remember();n.title=el.value;touch();return;}if(el.id==='editor'){remember();n.body=C.sanitize(el.innerHTML);touch();wordCount();return;}if(el.id==='markdown'){remember();n.body=el.value;touch();wordCount();return;}if(el.id==='setting-size'){state.settings.fontSize=Number(el.value);persist();colors();el.previousElementSibling.textContent='Yazı boyutu · '+el.value+' px';}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.taskCheck){const n=state.notes.find(n=>n.id===el.dataset.owner),t=n?.tasks.find(t=>t.id===el.dataset.taskCheck);if(t){t.done=el.checked;n.updated=Date.now();persist();render();}return;}if(el.id==='sort'){state.settings.sort=el.value;persist();updateLibrary();}if(el.id==='note-folder'){note().folder=el.value;touch();}if(el.id==='format-block'){command('formatBlock',el.value);}const mapping={'setting-theme':'theme','setting-font':'font','setting-folder':'defaultFolder','setting-goal':'weeklyGoal','setting-spell':'spellcheck'};if(mapping[el.id]){state.settings[mapping[el.id]]=el.id==='setting-spell'?el.checked:el.id==='setting-goal'?Math.min(100,Math.max(1,Number(el.value)||5)):el.value;persist();colors();}});
document.addEventListener('submit',e=>{if(e.target.id==='task-form'){e.preventDefault();const el=$('#new-task'),text=el.value.trim();if(!text)return;note().tasks.push({id:C.uid(),text,done:false,due:'',priority:'normal'});touch();render();$('#new-task').focus();}});
document.addEventListener('paste',e=>{if(e.target.closest('#editor')){e.preventDefault();command('insertText',e.clipboardData.getData('text/plain'));}});
document.addEventListener('drop',e=>{if(e.target.closest('#editor')){e.preventDefault();toast('Dosya eklemek için Ek ekle düğmesini kullan.');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();escapeBack();}if((e.ctrlKey||e.metaKey)&&!e.altKey){if(e.key.toLowerCase()==='s'){e.preventDefault();persist();toast('Kaydedildi.');}if(e.key.toLowerCase()==='n'){e.preventDefault();if(!fatal&&!welcome)newNote();}if(e.key.toLowerCase()==='k'){e.preventDefault();if(currentId)actions.back();$('#search')?.focus();}}if(e.key==='Enter'&&e.target.matches('[data-note]:not(button)')){e.preventDefault();openNote(e.target.dataset.note);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();});window.addEventListener('beforeunload',persist);matchMedia('(prefers-color-scheme:dark)').addEventListener('change',colors);
render();if(native&&!welcome&&!fatal){syncReminders();const id=Native.launchNote();if(id)window.openNotification(id);}
